html:
{%- set st = frappe.get_cached_doc("School Settings") -%}
{%- set a = st.statement_accent_color or "#1f6f5c" -%}
{%- set cur = st.currency -%}
{%- set money = frappe.utils.fmt_money -%}
{%- set after = doc.balance_after if doc.docstatus == 1 else (doc.balance_before or 0) - (doc.amount or 0) -%}
{%- set state = "CANCELLED" if doc.docstatus == 2 else ("PAID" if doc.docstatus == 1 else "DRAFT") -%}
<style>
  .rc { --a: {{ a }}; font-family: Helvetica, Arial, sans-serif; color: #1d2433; font-size: 11.5px; line-height: 1.4; position: relative; }
  .rc table { width: 100%; border-collapse: collapse; }
  .rc td, .rc th { vertical-align: top; }
  .rc .r { text-align: right; } .rc .c { text-align: center; }
  .rc .mu { color: #6b7280; font-size: 10.5px; }
  .rc .lbl { font-size: 9px; text-transform: uppercase; letter-spacing: 1px; color: #6b7280; font-weight: 700; margin-bottom: 3px; }
  .rc .val { font-size: 13px; font-weight: 700; }

  .rc .hd td { padding: 0; vertical-align: middle; }
  .rc .logo { max-height: 62px; max-width: 90px; }
  .rc .logo-cell { width: 78px; padding-right: 12px !important; }
  .rc .sn { font-size: 19px; font-weight: 800; color: {{ a }}; letter-spacing: -.2px; }
  .rc .tt { font-size: 22px; font-weight: 800; letter-spacing: 3px; color: #1d2433; }
  .rc .no { font-size: 12px; margin-top: 2px; }
  .rc .pill { display: inline-block; margin-top: 6px; padding: 3px 10px; border-radius: 20px; font-size: 9.5px; font-weight: 800; letter-spacing: 1.2px; }
  .rc .pill.PAID { background: #e7f6ee; color: #17633b; } .rc .pill.DRAFT { background: #fff4e5; color: #9a5b00; } .rc .pill.CANCELLED { background: #fdecea; color: #b42318; }
  .rc .rule { height: 4px; background: {{ a }}; margin: 14px 0 16px; border-radius: 2px; }

  .rc .box { border: 1px solid #e3e7ec; border-radius: 8px; padding: 10px 12px; }
  .rc .two { border-collapse: separate; border-spacing: 0; }
  .rc .two td { width: 50%; }
  .rc .two td.gap { width: 14px; padding: 0; }

  .rc .amt { margin: 14px 0; border-radius: 10px; background: {{ a }}; color: #fff; }
  .rc .amt td { padding: 14px 18px; vertical-align: middle; }
  .rc .amt .lbl { color: rgba(255,255,255,.75); }
  .rc .amt .big { font-size: 28px; font-weight: 800; letter-spacing: -.5px; }
  .rc .amt .words { font-size: 10.5px; opacity: .9; margin-top: 2px; }
  .rc .amt .meta { border-left: 1px solid rgba(255,255,255,.25); width: 38%; }
  .rc .amt .meta div.row { margin: 2px 0; font-size: 11px; }
  .rc .amt .meta b { font-weight: 700; }

  .rc .sec { font-size: 10px; text-transform: uppercase; letter-spacing: 1px; font-weight: 800; color: {{ a }}; margin: 16px 0 6px; }
  .rc .g th { font-size: 9px; text-transform: uppercase; letter-spacing: .8px; color: #4b5563; text-align: left; padding: 7px 8px; background: #f4f6f8; border-bottom: 1px solid #e3e7ec; }
  .rc .g th.r { text-align: right; }
  .rc .g td { padding: 7px 8px; border-bottom: 1px solid #eef1f4; }
  .rc .g tr.tot td { border-bottom: 0; border-top: 2px solid #1d2433; font-weight: 800; font-size: 12px; }
  .rc .g .num { font-variant-numeric: tabular-nums; white-space: nowrap; }

  .rc .sum { margin-top: 16px; }
  .rc .sum td { width: 33.33%; padding: 10px 12px; border: 1px solid #e3e7ec; }
  .rc .sum td.now { background: {{ a }}; color: #fff; border-color: {{ a }}; }
  .rc .sum td.now .lbl { color: rgba(255,255,255,.8); }
  .rc .sum .val { font-size: 15px; }

  .rc .sig { margin-top: 30px; }
  .rc .sig td { width: 33.33%; padding: 0 10px 0 0; vertical-align: bottom; }
  .rc .line { border-top: 1px solid #9aa3af; padding-top: 4px; margin-top: 26px; }
  .rc .stamp { border: 1.5px dashed #c5cbd3; border-radius: 8px; height: 70px; text-align: center; color: #b0b7c1; font-size: 9px; letter-spacing: 1px; padding-top: 28px; }

  .rc .ft { margin-top: 20px; padding-top: 10px; border-top: 1px solid #eef1f4; }
  .rc .ft td { font-size: 10px; color: #6b7280; vertical-align: middle; }
  .rc .wm { position: absolute; top: 300px; left: 0; right: 0; text-align: center; font-size: 90px; font-weight: 800; letter-spacing: 10px;
    color: rgba(180, 35, 24, .08); transform: rotate(-20deg); }
</style>

<div class="rc">
  {% if state != "PAID" %}<div class="wm">{{ state }}</div>{% endif %}

  <table class="hd"><tr>
    {% if st.school_logo %}<td class="logo-cell"><img src="{{ st.school_logo }}" class="logo"></td>{% endif %}
    <td>
      <div class="sn">{{ st.school_name or "" }}</div>
      {% if st.address %}<div class="mu">{{ st.address | replace("\n", ", ") }}</div>{% endif %}
      <div class="mu">{% if st.phone %}Tel {{ st.phone }}{% endif %}{% if st.phone and st.email %} &nbsp;&middot;&nbsp; {% endif %}{% if st.email %}{{ st.email }}{% endif %}</div>
    </td>
    <td class="r" style="width: 38%">
      <div class="tt">RECEIPT</div>
      <div class="no">No. <b>{{ doc.name }}</b></div>
      <div class="mu">{{ frappe.utils.formatdate(doc.posting_date, "d MMMM yyyy") }}</div>
      <span class="pill {{ state }}">{{ state }}</span>
    </td>
  </tr></table>
  <div class="rule"></div>

  <table class="two"><tr>
    <td class="box">
      <div class="lbl">Received from</div>
      <div class="val">{{ doc.payer_name or "Parent / Guardian" }}</div>
      {% if doc.payer_phone %}<div class="mu">{{ doc.payer_phone }}</div>{% endif %}
    </td>
    <td class="gap"></td>
    <td class="box">
      <div class="lbl">On behalf of student</div>
      <div class="val">{{ doc.student_name }}</div>
      <div class="mu">Adm. {{ doc.student }}{% if doc.school_class %} &nbsp;&middot;&nbsp; {{ doc.school_class }}{% endif %}</div>
    </td>
  </tr></table>

  <table class="amt"><tr>
    <td>
      <div class="lbl">Amount received</div>
      <div class="big">{{ money(doc.amount, currency=cur) }}</div>
      <div class="words">{{ frappe.utils.money_in_words(doc.amount, cur) }}</div>
    </td>
    <td class="meta">
      <div class="row">Method: <b>{{ doc.mode_of_payment or "-" }}</b></div>
      {% if doc.reference_no %}<div class="row">Ref: <b>{{ doc.reference_no }}</b></div>{% endif %}
      <div class="row">Date: <b>{{ frappe.utils.formatdate(doc.posting_date, "d MMM yyyy") }}</b></div>
    </td>
  </tr></table>

  {% if doc.allocations or doc.unallocated_amount %}
  <div class="sec">Payment applied to</div>
  <table class="g">
    <thead><tr><th style="width:28px">#</th><th>Fee</th><th>Term</th><th>Invoice</th><th class="r">Amount</th></tr></thead>
    <tbody>
      {% for r in doc.allocations %}
      <tr><td class="mu">{{ loop.index }}</td><td><b>{{ r.fee_type }}</b></td><td>{{ r.school_term or "" }}</td><td class="mu">{{ r.sales_invoice or "" }}</td>
        <td class="r num">{{ money(r.allocated_amount, currency=cur) }}</td></tr>
      {% endfor %}
      {% if doc.unallocated_amount %}
      <tr><td class="mu">{{ (doc.allocations | length) + 1 }}</td><td><b>Advance</b></td><td colspan="2" class="mu">Held for future fees</td>
        <td class="r num">{{ money(doc.unallocated_amount, currency=cur) }}</td></tr>
      {% endif %}
      <tr class="tot"><td></td><td colspan="3">Total</td><td class="r num">{{ money(doc.amount, currency=cur) }}</td></tr>
    </tbody>
  </table>
  {% endif %}

  <table class="sum"><tr>
    <td><div class="lbl">Previous balance</div><div class="val">{{ money(doc.balance_before or 0, currency=cur) }}</div></td>
    <td><div class="lbl">Less this payment</div><div class="val">{{ money(doc.amount, currency=cur) }}</div></td>
    <td class="now"><div class="lbl">{{ "Credit on account" if after < 0 else "Balance now" }}</div><div class="val">{{ money(after if after >= 0 else -after, currency=cur) }}</div></td>
  </tr></table>

  <table class="sig"><tr>
    <td><div class="line"><div class="lbl">Received by</div>{{ frappe.get_fullname(doc.owner) }}</div></td>
    <td><div class="line"><div class="lbl">Signature</div>&nbsp;</div></td>
    <td><div class="stamp">OFFICIAL STAMP</div></td>
  </tr></table>

  <table class="ft"><tr>
    <td>Thank you for your payment. Please keep this receipt for your records.
      {% if st.paybill_number and (st.mpesa_account_type or "").startswith("Till") %}<br>Pay fees via M-Pesa Buy Goods, Till <b>{{ st.paybill_number }}</b>.{% elif st.paybill_number %}<br>Pay fees via M-Pesa Paybill <b>{{ st.paybill_number }}</b>, Account No. <b>{{ doc.student }}</b>.{% endif %}</td>
    <td class="r" style="width: 32%">Printed {{ frappe.utils.format_datetime(frappe.utils.now_datetime(), "d MMM yyyy, HH:mm") }}</td>
  </tr></table>
</div>
